speakingExercises["teen-life"].push(
  { title: "My daily hobby — 45-second talk", situation: "Günlük hobilerini yeni tanıştığın bir gence anlat.", task: "Hobini ne zaman ve kiminle yaptığını, neden sevdiğini ve sevmediğin bir etkinliği anlat. En az beş cümle kur.", phrases: "I usually... after school. · I like/love... because... · I don't like... · I enjoy + verb-ing...", challenge: "Simple Present kullan; usually, sometimes veya never zarflarından birini ekle.", model: "On weekdays, I usually finish my homework at five. Then I play basketball with my friends. I like team sports because they are exciting. I don't like staying indoors all day. I enjoy riding my bike at weekends." },
  { title: "Hobby interview and report", situation: "Bir arkadaşına günlük hobilerini sor, sonra onu sınıfa tanıt.", task: "Beş soru sor: okuldan sonra ne yapar, neyi sever/sevmez, ne sıklıkta yapar ve kiminle yapar? Ardından 4 cümleyle rapor et.", phrases: "What do you usually do after school? · Do you like...? · How often do you...? · My friend likes... · He/She doesn't like...", challenge: "Raporunda üçüncü tekil kişi eklerini kullan: likes, enjoys, doesn't like.", model: "My friend Elif usually draws after school. She likes making comics and enjoys listening to music. She doesn't like playing football. She sometimes shares her drawings with her cousin." },
  { title: "Likes, dislikes and a new hobby", situation: "Bir arkadaşın yeni bir hobi arıyor. İkiniz seçenekleri konuşup öneri yapın.", task: "Üç etkinliği karşılaştırın. Her kişi bir şeyi sevdiğini, bir şeyi sevmediğini söylesin; sonunda ortak bir hobi seçin.", phrases: "I like... · I don't like... · Do you enjoy...? · He/She prefers... · Let's try...", challenge: "Bir Like/Doesn't like ifadesiyle günlük bir rutin cümlesi de ekle.", model: "I like cycling, but I don't like running. My friend likes taking photos. She doesn't enjoy team sports. We both enjoy walking in the park, so we go there after school." }
);

